<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['user_skill_id']??0);if($action==='delete'){$s=$pdo->prepare("DELETE FROM UserSkills WHERE user_skill_id=? AND user_id=?");$s->execute([$id,$uid]);flash('success','Skill removed.');}redirect('my-skills.php');}
$s=$pdo->prepare("SELECT us.*,s.skill_name,c.category_name FROM UserSkills us JOIN Skills s ON s.skill_id=us.skill_id JOIN SkillCategories c ON c.category_id=s.category_id WHERE us.user_id=? ORDER BY us.skill_type,s.skill_name");$s->execute([$uid]);$rows=$s->fetchAll();$title='My skills';include 'includes/header.php';
?>
<div class="page-head"><div><div class="eyebrow">YOUR SKILLS</div><h1>What can you swap?</h1></div><a class="btn" href="add-skill.php">+ Add skill</a></div><div class="card table-wrap"><table><thead><tr><th>Skill</th><th>Type</th><th>Level</th><th>Experience</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['skill_name'])?></b><small><?=e($r['category_name'])?></small></td><td><span class="badge <?=$r['skill_type']?>"><?=strtoupper($r['skill_type'])?></span></td><td><?=e($r['proficiency_level'])?></td><td><?=e($r['years_experience'])?> yrs</td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="user_skill_id" value="<?=$r['user_skill_id']?>"><button class="link danger">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div>
